let language='en';try{language=localStorage.getItem('cv-language')==='tr'?'tr':'en'}catch{}window.t=text=>language==='tr'?(translations[text]||text):text;window.courseLanguage=()=>language;
const textNodes=[];const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('script,style,#modules,#characteristic-note')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});while(walker.nextNode()){const node=walker.currentNode;const key=node.textContent.trim();if(translations[key])textNodes.push({node,key,original:node.textContent})}const attrs=[];document.querySelectorAll('[aria-label],[placeholder]').forEach(node=>{for(const attr of ['aria-label','placeholder'])if(node.hasAttribute(attr))attrs.push({node,attr,key:node.getAttribute(attr)})});
const controls=document.createElement('div');controls.className='preferences';controls.innerHTML='<div class="language-switch" role="group" aria-label="Language / Dil"><button type="button" data-lang="tr">TR</button><button type="button" data-lang="en">EN</button></div><button class="valve-toggle" type="button" role="switch"><span class="valve-art" aria-hidden="true"><span class="actuator"></span><span class="valve-stem"></span><span class="valve-pipe"></span><span class="valve-body"></span></span><span class="theme-label"></span></button>';document.querySelector('header').append(controls);
function applyLanguage(next){language=next;try{localStorage.setItem('cv-language',next)}catch{}document.documentElement.lang=next;document.title=next==='tr'?'Kontrol Vanası — Mühendislik Akademisi':'Control Valve — Engineering Academy';document.querySelector('meta[name="description"]').content=next==='tr'?'Müh. R. Mahjoub ile 32 saatlik kontrol vanası eğitimi. Sekiz modül, dört günlük program ve etkileşimli vana laboratuvarı.':'A 32-hour control valve course with Eng. R. Mahjoub. Eight modules, a four-day learning plan and an interactive valve lab.';textNodes.forEach(({node,key,original})=>{node.textContent=next==='tr'?original.replace(key,translations[key]):original});attrs.forEach(({node,attr,key})=>node.setAttribute(attr,t(key)));controls.querySelectorAll('[data-lang]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.lang===next))});setThemeLabel();window.dispatchEvent(new Event('languagechange'))}controls.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>applyLanguage(b.dataset.lang)));
let theme;try{theme=localStorage.getItem('cv-theme')}catch{}if(!['light','dark'].includes(theme))theme=matchMedia('(prefers-color-scheme: light)').matches?'light':'dark';function setThemeLabel(){const button=controls.querySelector('.valve-toggle');const light=theme==='light';button.setAttribute('aria-checked',String(light));button.setAttribute('aria-label',language==='tr'?'Açık tema': 'Light theme');button.title=language==='tr'?'Vana anahtarı ile temayı değiştir':'Switch theme with the valve control';button.querySelector('.theme-label').textContent=language==='tr'?(light?'AÇIK':'KOYU'):(light?'LIGHT':'DARK')}function applyTheme(){document.documentElement.dataset.theme=theme;document.querySelector('meta[name="theme-color"]').content=theme==='light'?'#f4f2eb':'#131716';setThemeLabel()}controls.querySelector('.valve-toggle').addEventListener('click',()=>{theme=theme==='light'?'dark':'light';try{localStorage.setItem('cv-theme',theme)}catch{}applyTheme()});applyTheme();applyLanguage(language);
